import { applyTranslationOverrides, createI18n, translateError, translateValidation as translateSharedValidation, type Language } from '@vero/i18n';
import type { TFunction } from 'i18next';
import { getCurrentLanguage } from './language';

/**
 * Admin i18n instance: shared namespaces (common, shop, validation, errors) + the app namespace `admin`
 * (generated by scripts/i18n/build.mjs). Missing keys fall back to common → shop, missing languages to uz.
 * The `admin` texts of a language are downloaded when that language is first used (one chunk each), so the
 * panel does not ship all three languages up front.
 */
export const i18n = createI18n({
  lng: getCurrentLanguage(),
  resources: { uz: { admin: {} }, ru: { admin: {} }, en: { admin: {} } },
  defaultNS: 'admin',
  // re-render when texts are added to the store (a language bundle, translation overrides)
  init: { react: { useSuspense: false, bindI18nStore: 'added' } },
});

const ADMIN_LOCALES: Record<Language, () => Promise<{ default: Record<string, unknown> }>> = {
  uz: () => import('@vero/i18n/locales/uz/admin.json'),
  ru: () => import('@vero/i18n/locales/ru/admin.json'),
  en: () => import('@vero/i18n/locales/en/admin.json'),
};
const loading = new Map<Language, Promise<void>>();

/** Loads the admin texts of a language once; overrides already applied for it are kept. */
export function loadAdminLocale(lng: Language): Promise<void> {
  let pending = loading.get(lng);
  if (!pending) {
    pending = ADMIN_LOCALES[lng]().then((mod) => {
      i18n.addResourceBundle(lng, 'admin', mod.default, true, false);
    });
    pending.catch(() => loading.delete(lng));
    loading.set(lng, pending);
  }
  return pending;
}

/** Resolves when the texts of the starting language are in place (main.tsx renders after it). */
export const i18nReady: Promise<void> = loadAdminLocale(getCurrentLanguage());

const applied = new Set<string>();

/** Applies texts edited on the Translations screen once per language and revision. */
export function applyOverrides(lng: Language, resources: Record<string, Record<string, string>>, revision = ''): void {
  const key = `${lng}:${revision}`;
  if (applied.has(key)) return;
  applied.add(key);
  applyTranslationOverrides(i18n, lng, resources);
}

/** Error text for any thrown value (ApiError, network error, unknown). */
export function errorMessage(t: TFunction, error: unknown, params?: Record<string, unknown>): string {
  if (error && typeof error === 'object' && 'code' in error) {
    return translateError(t, error as { code?: string; message?: string }, params);
  }
  return String(t('errors:UNKNOWN'));
}

/** Field error text: shared `validation.*` / `errors.*` keys, or an admin key such as `settings.installment.duplicate`. */
export function translateValidation(t: TFunction, message: string | undefined): string | undefined {
  const text = translateSharedValidation(t, message);
  if (text && text === message && i18n.exists(message, { ns: 'admin' })) return String(t(message));
  return text;
}
